import { randomUUID } from "node:crypto";
import typia from "typia";
import { create_owner, type OwnerFixture } from "../../../helpers/ErpFixtures";
import { MyGlobal } from "../../../../src/MyGlobal";

async function procurementFixture(connection: api.IConnection): Promise<OwnerFixture & { unitId: string; vendorId: string; customerId: string; itemId: string; warehouseId: string; locationId: string }> {
  const owner = await create_owner(connection);
  const suffix = `${Date.now()}${Math.floor(Math.random() * 10000)}`;
  const unit = await api.functional.erp.unit.unitCreate(owner.connection, { code: `U${suffix.slice(-8)}`, name: "Each", category: "quantity" });
  const vendor = await api.functional.erp.party.partyCreate(owner.connection, { kind: "vendor", name: `Vendor ${suffix}`, currency: "USD" });
  const customer = await api.functional.erp.party.partyCreate(owner.connection, { kind: "customer", name: `Customer ${suffix}`, currency: "USD" });
  const item = await api.functional.erp.item.itemCreate(owner.connection, { sku: `SKU-${suffix}`, name: "Inventory", type: "inventory", unitId: unit.id, trackingMode: "none" });
  const warehouse = await api.functional.erp.warehouse.warehouseCreate(owner.connection, { code: `W${suffix.slice(-8)}`, name: "Main" });
  const location = await api.functional.erp.location.locationCreate(owner.connection, { warehouseId: warehouse.id, code: `L${suffix.slice(-8)}` });
  return { ...owner, unitId: unit.id, vendorId: vendor.id, customerId: customer.id, itemId: item.id, warehouseId: warehouse.id, locationId: location.id };
}

/** Proves production planning evidence and service-case SLA fields survive API round trips and filters. */
export async function test_api_erp_planning_and_service_sla_evidence(connection: api.IConnection): Promise<void> {
  const fixture = await procurementFixture(connection);
  const order = await api.functional.erp.operations.production.productionCreate(fixture.connection, { finishedItemId: fixture.itemId, plannedQuantity: 4, plannedMaterialCost: 20, plannedLaborCost: 30, plannedMachineCost: 10, plannedOverheadCost: 5, warehouseId: fixture.warehouseId, locationId: fixture.locationId });
  if (order.plannedMaterialCost !== 20 || order.plannedLaborCost !== 30 || order.plannedMachineCost !== 10 || order.plannedOverheadCost !== 5 || order.actualMaterialCost !== 0 || order.variance !== 0) throw new Error("Production planned and actual cost evidence was not persisted.");
  const due = new Date(Date.now() + 60 * 60 * 1000).toISOString();
  const service = await api.functional.erp.operations.service.serviceCreate(fixture.connection, { customerId: fixture.customerId, priority: "urgent", slaDueAt: due, description: "SLA evidence" });
  if (service.priority !== "urgent" || service.slaDueAt !== due) throw new Error("Service-case priority and SLA timing were not returned.");
  const filtered = await api.functional.erp.operations.service.serviceIndex(fixture.connection, { page: 1, limit: 10, slaState: "within_sla" });
  if (!filtered.data.some((row) => row.id === service.id)) throw new Error("Service-case SLA filtering did not return an in-SLA case.");
  const cancelled = await api.functional.erp.operations.service.serviceCreate(fixture.connection, { customerId: fixture.customerId, priority: "normal", slaDueAt: due, description: "Cancelled SLA case" });
  await api.functional.erp.operations.service.serviceState(fixture.connection, cancelled.id, "cancelled", {});
  const afterCancellation = await api.functional.erp.operations.service.serviceIndex(fixture.connection, { page: 1, limit: 10, slaState: "within_sla" });
  if (afterCancellation.data.some((row) => row.id === cancelled.id)) throw new Error("Cancelled service cases were incorrectly classified as active within-SLA work.");
  const report = await api.functional.erp.control.report.report(fixture.connection, { kind: "service_case_sla", from: null, to: null });
  const within = report.rows.find((row) => row.label === "service_cases_within_sla");
  if (within?.value !== 1) throw new Error(`Service-case SLA report did not expose the active within-SLA count: ${within?.value}`);
}

async function vendorBillSource(fixture: OwnerFixture & { unitId: string; vendorId: string; itemId: string; warehouseId: string; locationId: string }, quantity: number, unitPrice: number): Promise<{ id: string }> {
  const order = await api.functional.erp.purchase.order.orderCreate(fixture.connection, { vendorId: fixture.vendorId, currency: "USD", sourceRequestId: null, lines: [{ itemId: fixture.itemId, orderedQuantity: quantity, unitPrice, unitId: fixture.unitId, warehouseId: fixture.warehouseId }] });
  const submitted = await api.functional.erp.purchase.order.orderTransition(fixture.connection, order.id, "submitted");
  const approved = await api.functional.erp.purchase.order.orderTransition(fixture.connection, submitted.id, "approved");
  const sent = await api.functional.erp.purchase.order.orderTransition(fixture.connection, approved.id, "sent");
  const line = sent.lines[0];
  if (line === undefined) throw new Error("Vendor bill source did not return a purchase line.");
  const receipt = await api.functional.erp.purchase.receipt.receiptCreate(fixture.connection, { orderId: sent.id, lines: [{ orderLineId: line.id, receivedQuantity: quantity, acceptedQuantity: quantity, rejectedQuantity: 0, warehouseId: fixture.warehouseId, locationId: fixture.locationId }] });
  await api.functional.erp.purchase.receipt.post.receiptPost(fixture.connection, receipt.id);
  return line;
}

/** Proves fixed-asset transfer, impairment, disposal gain/loss, and retirement events remain durable. */
export async function test_api_erp_asset_events(connection: api.IConnection): Promise<void> {
  const fixture = await procurementFixture(connection);
  const created = await api.functional.erp.operations.asset.assetCreate(fixture.connection, { tag: `EVENT-${Date.now()}`, name: "Event Asset", acquisitionCost: 1000, residualValue: 100, usefulLifeMonths: 60, depreciationMethod: "straight_line" });
  const active = await api.functional.erp.operations.asset.assetUpdate(fixture.connection, created.id, { status: "active" });
  const transferred = await api.functional.erp.operations.asset.transfer.assetTransfer(fixture.connection, active.id, { reason: "Move to operations" });
  if (transferred.assetId !== active.id || transferred.reason !== "Move to operations") throw new Error("Asset transfer evidence was not persisted.");
  const impairment = await api.functional.erp.operations.asset.impair.assetImpair(fixture.connection, active.id, { amount: 100, reason: "Damage" });
  if (impairment.carryingValueAfter !== 900) throw new Error("Asset impairment did not reduce carrying value.");
  const organization = await MyGlobal.prisma.memberships.findUniqueOrThrow({ where: { id: fixture.membershipId }, select: { organization_id: true } });
  const impairmentJournal = await MyGlobal.prisma.journals.findFirst({ where: { organization_id: organization.organization_id, source_module: "asset_impairment", source_id: impairment.id, status: "posted" }, select: { id: true } });
  if (impairmentJournal === null) throw new Error("Asset impairment did not create a source-linked posted journal.");
  const disposal = await api.functional.erp.operations.asset.dispose.assetDispose(fixture.connection, active.id, { type: "sale", reason: "Replacement", proceeds: 950 });
  if (disposal.carryingValue !== 900 || disposal.gainOrLoss !== 50) throw new Error("Asset disposal gain/loss was not calculated from carrying value.");
  const disposalJournal = await MyGlobal.prisma.journals.findFirst({ where: { organization_id: organization.organization_id, source_module: "asset_disposal", source_id: disposal.id, status: "posted" }, select: { id: true } });
  if (disposalJournal === null) throw new Error("Asset disposal did not create a source-linked posted journal.");
  const disposalLines = await MyGlobal.prisma.journal_lines.findMany({ where: { journal_id: disposalJournal.id }, select: { debit: true, credit: true } });
  if (disposalLines.length < 2 || Math.abs(disposalLines.reduce((sum, line) => sum + line.debit, 0) - disposalLines.reduce((sum, line) => sum + line.credit, 0)) > 0.000001) throw new Error("Asset disposal journal was not balanced.");
  const retired = await api.functional.erp.operations.asset.retire.assetRetire(fixture.connection, active.id);
  if (retired.status !== "retired") throw new Error("Disposed asset was not retired.");
}

