/** Proves reversing a paid payroll run also reverses its payment and bank movement. */
export async function test_api_erp_paid_payroll_reversal_effects(connection: api.IConnection): Promise<void> { const owner = await create_owner(connection); await api.functional.erp.workforce.employee.employeeCreate(owner.connection, { employeeNumber: `PAY-R-${Date.now()}`, department: "Finance" }); const account = await api.functional.erp.account.create(owner.connection, { code: `PR${Date.now()}`.slice(-8), name: "Payroll reversal bank", type: "asset", parentId: null, currency: "USD" }); const bank = await api.functional.erp.control_ops.bank_account.bankCreate(owner.connection, { ledgerAccountId: account.id, name: "Payroll reversal bank", maskedNumber: "****9010", openingBalance: 100 }); const run = await api.functional.erp.workforce.payroll.payrollCreate(owner.connection, { period: "2026-08", total: 10, scheduleId: null, paymentDate: null }); await api.functional.erp.workforce.payroll.calculate.payrollCalculate(owner.connection, run.id); const approved = await api.functional.erp.workforce.payroll.approve.payrollApprove(owner.connection, run.id); const posted = await api.functional.erp.workforce.payroll.post.payrollPost(owner.connection, approved.id); const paid = await api.functional.erp.workforce.payroll.pay.payrollPay(owner.connection, posted.id, { bankAccountId: bank.id }); const reversed = await api.functional.erp.workforce.payroll.reverse.payrollReverse(owner.connection, paid.id); const organization = await MyGlobal.prisma.memberships.findUniqueOrThrow({ where: { id: owner.membershipId }, select: { organization_id: true } }); const payment = await MyGlobal.prisma.payments.findFirst({ where: { organization_id: organization.organization_id, bank_account_id: bank.id, amount: 10 }, orderBy: { created_at: "desc" } }); if (payment?.status !== "reversed") throw new Error("Paid payroll reversal did not reverse the payment."); const movements = await MyGlobal.prisma.bank_transactions.findMany({ where: { organization_id: organization.organization_id, bank_account_id: bank.id, matched_target_type: { in: ["payroll", "payroll_reversal"] }, matched_target_id: { in: [paid.id, reversed.id] } } }); if (movements.length !== 2 || !movements.some((movement) => movement.amount === -10) || !movements.some((movement) => movement.amount === 10)) throw new Error("Paid payroll reversal did not preserve both bank movements."); }

