export async function test_api_erp_service_order_cancel(connection: api.IConnection): Promise<void> { const fixture = await procurementFixture(connection); const order = await api.functional.erp.service_order.create(fixture.connection, { customerId: fixture.customerId, caseId: null, scheduledAt: null }); const cancelled = await api.functional.erp.service_order.cancel(fixture.connection, order.id); if (cancelled.status !== "cancelled") throw new Error("Service-order cancellation was not persisted."); }

/** Proves tag discovery and removal are scoped to the concrete target. */
export async function test_api_erp_tag_target_commands(connection: api.IConnection): Promise<void> { const owner = await create_owner(connection); const target = await api.functional.erp.party.partyCreate(owner.connection, { kind: "customer", name: `Tag Target ${Date.now()}`, currency: "USD" }); const targetId = target.id; const tag = await api.functional.erp.interaction.tag.tagCreate(owner.connection, { label: `target-${targetId.slice(0, 8)}`, description: null }); await api.functional.erp.interaction.tag.assign.tagAssign(owner.connection, tag.id, { targetType: "party", targetId }); const found = await api.functional.erp.interaction.tag.tagIndex(owner.connection, "party", targetId); if (!found.some((row) => row.id === tag.id)) throw new Error("Assigned tag was not discoverable for its target."); await api.functional.erp.interaction.tag.assign.tagUnassign(owner.connection, tag.id, "party", targetId); const after = await api.functional.erp.interaction.tag.tagIndex(owner.connection, "party", targetId); if (after.some((row) => row.id === tag.id)) throw new Error("Tag assignment was not removed."); await api.functional.erp.interaction.tag.tagErase(owner.connection, tag.id); }

/** Proves vendor-bank and customer-credit changes require resolution before application. */
export async function test_api_erp_party_change_approval(connection: api.IConnection): Promise<void> { const owner = await create_owner(connection); const vendor = await api.functional.erp.party.partyCreate(owner.connection, { kind: "vendor", name: `Bank change ${Date.now()}`, taxIdentity: null, currency: "USD", paymentTermId: null, creditLimit: null, primaryContactId: null, billingAddressId: null, shippingAddressId: null, country: null, riskLevel: null, notes: null }); const bankRequest = await api.functional.erp.party.change_request.partyChangeCreate(owner.connection, vendor.id, { kind: "bank_account", proposedValue: "****9988", reason: "Verified supplier letter" }); const bankApproved = await api.functional.erp.party.change_request.transition.partyChangeResolve(owner.connection, bankRequest.id, "approved"); await api.functional.erp.party.change_request.apply.partyChangeApply(owner.connection, bankApproved.id); const bankParty = await api.functional.erp.party.partyAt(owner.connection, vendor.id); if (bankParty.bankAccountReference !== "****9988") throw new Error("Approved vendor bank change was not applied."); const customer = await api.functional.erp.party.partyCreate(owner.connection, { kind: "customer", name: `Credit change ${Date.now()}`, taxIdentity: null, currency: "USD", paymentTermId: null, creditLimit: 100, primaryContactId: null, billingAddressId: null, shippingAddressId: null, country: null, riskLevel: null, notes: null }); const creditRequest = await api.functional.erp.party.change_request.partyChangeCreate(owner.connection, customer.id, { kind: "credit_limit", proposedValue: "500", reason: "Credit review" }); await api.functional.erp.party.change_request.transition.partyChangeResolve(owner.connection, creditRequest.id, "rejected"); const unchanged = await api.functional.erp.party.partyAt(owner.connection, customer.id); if (unchanged.creditLimit !== 100) throw new Error("Rejected customer credit change mutated the party."); }

/** Proves inspection execution records characteristic results before final quality disposition. */
export async function test_api_erp_inspection_results(connection: api.IConnection): Promise<void> { const fixture = await procurementFixture(connection); const inspection = await api.functional.erp.operations.inspection.inspectionCreate(fixture.connection, { itemId: fixture.itemId, inspectionPlanId: null, sourceType: "receipt", sourceId: null }); const started = await api.functional.erp.operations.inspection.start.inspectionStart(fixture.connection, inspection.id); const recorded = await api.functional.erp.operations.inspection.results.inspectionResults(fixture.connection, started.id, { results: { weight: 10, visual: "pass" } }); if (recorded.results.visual !== "pass") throw new Error("Inspection characteristic results were not persisted."); const finalized = await api.functional.erp.operations.inspection.inspectionFinalize(fixture.connection, recorded.id, "passed"); if (finalized.status !== "passed") throw new Error("Inspection result was not finalized."); }

/** Proves an overdue maintenance plan generates a version-pinned work order. */
export async function test_api_erp_maintenance_plan_generation(connection: api.IConnection): Promise<void> { const fixture = await procurementFixture(connection); const equipment = await api.functional.erp.operations.equipment.equipmentCreate(fixture.connection, { tag: `PLAN-EQ-${Date.now()}`, name: "Press", criticality: "medium", warehouseId: fixture.warehouseId }); const plan = await api.functional.erp.quality_maintenance_plan.maintenance.maintenanceCreate(fixture.connection, { equipmentId: equipment.id, frequencyDays: 30, checklist: ["Inspect"], requiredParts: [fixture.itemId], laborSkills: ["mechanic"], nextDueAt: "2026-01-01T00:00:00.000Z" }); const generated = await api.functional.erp.quality_maintenance_plan.maintenance.generate.maintenanceGenerate(fixture.connection, plan.id); if (generated.status !== "draft" || generated.equipmentId !== equipment.id) throw new Error("Due maintenance plan did not generate a work order."); }

/** Proves approval delegation and escalation remain in immutable approval history. */
export async function test_api_erp_approval_commands(connection: api.IConnection): Promise<void> { const owner = await create_owner(connection); const approval = await api.functional.erp.control_ops.approval.approvalCreate(owner.connection, { targetType: "vendor_bank_change", targetId: randomUUID() }); let rejected = false; try { await api.functional.erp.control_ops.approval.delegate.approvalDelegate(owner.connection, approval.id, { delegateTo: owner.membershipId }); } catch { rejected = true; } if (!rejected) throw new Error("Approval delegation must reject the current approver as delegate."); const escalated = await api.functional.erp.control_ops.approval.escalate.approvalEscalate(owner.connection, approval.id); if (escalated.currentStep !== approval.currentStep) throw new Error("Approval escalation must keep the current step assigned to its fallback approver."); const history = await api.functional.erp.control_ops.approval.history.approvalHistory(owner.connection, approval.id); if (history.length !== 2 || !history.some((row) => row.action === "requested") || !history.some((row) => row.action === "escalated")) throw new Error("Approval request and escalation history were not retained."); }

/** Proves one immutable audit event can be retrieved with before/after snapshots. */
export async function test_api_erp_audit_detail(connection: api.IConnection): Promise<void> { const owner = await create_owner(connection); await api.functional.erp.organization.update(owner.connection, { name: "Audited Organization" }); const events = await api.functional.erp.control.audit.auditIndex(owner.connection, { page: 1, limit: 20, action: "organization.updated", targetType: "organization", risk: null }); const event = events.data[0]; if (event === undefined) throw new Error("Organization update did not emit an audit event."); const detail = await api.functional.erp.control.audit.auditAt(owner.connection, event.id); if (detail.id !== event.id || detail.afterValue === null) throw new Error("Audit detail did not preserve the after snapshot."); }

/** Proves production actual-cost categories are recorded before closure variance is posted. */
export async function test_api_erp_production_cost_evidence(connection: api.IConnection): Promise<void> {
  const fixture = await procurementFixture(connection);
  const order = await api.functional.erp.operations.production.productionCreate(fixture.connection, { finishedItemId: fixture.itemId, plannedQuantity: 1, warehouseId: fixture.warehouseId, locationId: fixture.locationId });
  const released = await api.functional.erp.operations.production.release.productionRelease(fixture.connection, order.id);
  const started = await api.functional.erp.operations.production.start.productionStart(fixture.connection, released.id);
  const labor = await api.functional.erp.operations.production.labor.productionLabor(fixture.connection, started.id, { hours: 2, rate: 10 });
  const machine = await api.functional.erp.operations.production.machine_time.productionMachineTime(fixture.connection, labor.id, { hours: 1, rate: 5 });
  const overhead = await api.functional.erp.operations.production.overhead.productionOverhead(fixture.connection, machine.id, { amount: 3, reason: "Factory overhead" });
  if (overhead.laborCost !== 20 || overhead.machineCost !== 5 || overhead.overheadCost !== 3)
    throw new Error("Production actual labor, machine, and overhead costs were not persisted.");
}

/** Proves draft production edits keep BOM selection tied to the finished item. */
export async function test_api_erp_production_update_rejects_mismatched_bom(connection: api.IConnection): Promise<void> {
  const fixture = await procurementFixture(connection);
  const otherItem = await api.functional.erp.item.itemCreate(fixture.connection, { sku: `OTHER-${Date.now()}`, name: "Other finished item", type: "inventory", unitId: fixture.unitId, trackingMode: "none" });
  const bom = await api.functional.erp.operations.bom.bomCreate(fixture.connection, { finishedItemId: otherItem.id, lines: [{ itemId: fixture.itemId, quantity: 1 }] });
  const activeBom = await api.functional.erp.operations.bom.activate.bomActivate(fixture.connection, bom.id);
  const order = await api.functional.erp.operations.production.productionCreate(fixture.connection, { finishedItemId: fixture.itemId, plannedQuantity: 1 });
  let refused = false;
  try { await api.functional.erp.operations.production.productionUpdate(fixture.connection, order.id, { bomId: activeBom.id }); } catch { refused = true; }
  if (!refused) throw new Error("A draft production update accepted a BOM for a different finished item.");
}
